def spans(g,fg):
    H,W=len(g),len(g[0])
    rowspans={}; colspans={}
    for r in range(H):
        cs=[c for c in range(W) if g[r][c]==fg]
        if len(cs)>=2: rowspans[r]=(min(cs),max(cs))
    for c in range(W):
        rs=[r for r in range(H) if g[r][c]==fg]
        if len(rs)>=2: colspans[c]=(min(rs),max(rs))
    return rowspans,colspans
