def all_spans(g, fg):
    R,C=len(g),len(g[0]); out=[]
    for r in range(R):
        pos=[c for c in range(C) if g[r][c]==fg]
        for a,b in zip(pos,pos[1:]): out.append(('row',r,a,b,b-a-1))
    for c in range(C):
        pos=[r for r in range(R) if g[r][c]==fg]
        for a,b in zip(pos,pos[1:]): out.append(('col',c,a,b,b-a-1))
    return out
